import sys
(A, B, C, D) = map(int, sys.stdin.readline().split())
cols = 49
rows = 50
res = [['.' for i in range(cols)] for j in range(rows)]
A -= 1
B -= 1
for r in range(rows // 2):
	for c in range(cols):
		if r % 2 == 0 or c % 2 == 0:
			res[r][c] = 'A'
		elif B > 0:
			res[r][c] = 'B'
			B -= 1
		elif C > 0:
			res[r][c] = 'C'
			C -= 1
		elif D > 0:
			res[r][c] = 'D'
			D -= 1
		else:
			res[r][c] = 'A'
for r in range(rows // 2, rows):
	for c in range(cols):
		if r % 2 == 1 or c % 2 == 0:
			res[r][c] = 'B'
		elif A > 0:
			res[r][c] = 'A'
			A -= 1
		elif C > 0:
			res[r][c] = 'C'
			C -= 1
		elif D > 0:
			res[r][c] = 'D'
			D -= 1
		else:
			res[r][c] = 'B'
print(rows, cols)
print('\n'.join((''.join(r) for r in res)))
